from core.rules import RuleMachine


class RepairGoodTopFreeingMove:
    """Mueve un tope bien puesto de una pila aún mal ordenada para destapar contenedores bloqueados."""

    name = "repair_good_top_freeing_move"

    def __init__(self, prefer_empty: bool = True):
        self.prefer_empty = prefer_empty

    def allowed(self, partial, memory, candidates):
        res = []
        for a in candidates:
            so = a.so
            sd = a.sd

            if partial.h(so) == 0 or partial.h(sd) >= partial.H:
                continue

            # Tope del origen
            moved = partial.g(so)

            # El origen debe tener al menos un contenedor mal puesto debajo del tope:
            # si la pila estuviera ordenada, este movimiento sería poco útil para el desatasco.
            if partial.is_sorted_stack(so):
                continue

            # El contenedor movido debe estar bien puesto en el origen.
            if partial.h(so) > partial.sorted_n[so]:
                continue

            # Destino: preferimos hueco vacío, o bien que el contenedor quede bien puesto.
            if partial.h(sd) == 0:
                if self.prefer_empty:
                    res.append(a)
                continue

            if partial.g(sd) >= moved:
                res.append(a)

        return res


def build_component(problem, **params):
    prefer_empty = bool(params.get("prefer_empty", COMPONENT["params"]["prefer_empty"]["default"]))
    return RuleMachine(problem, [RepairGoodTopFreeingMove(prefer_empty=prefer_empty)])
